`timescale 1ps/1ps
// ---------------------------------------------------------------------------
// Unit bench of the host path of the GPU-organised HBM comparator system:
//   ot_host_if (MODE 0, parameters as instantiated in ot_gpu_hbm_system.sv)
//   -> ot_gpu_host_bridge (ENABLE 1, ND 2, NSM 2, CB 8, IMW 13)
//   -> 2 x ot_gpu_cmdproc (ENABLE 1, NSM 2) -> behavioural SM stubs,
// with every domain reset generated by ot_gpu_reset_ctrl from one por_n.
// The bench is the host (driver.py's protocol): AXI4-Lite BAR writes, a
// behavioural host memory answering the single-beat AXI4 DMA, SQ at 0x0000
// (LOG2 6), CQ at 0x1000 (LOG2 8), prompts at 0x10000 + slot * 0x400, the
// SQ_TAIL doorbell, CQ polling by phase bit and the CQ_HEAD doorbell.
// Before the first request the bridge loader port loads a 4-command graph
// (3 LAUNCH, END) into each die's command processor and 100 instruction
// words per SM.  SM stubs answer launches after 10..300 clk_sm cycles; SM 0
// posts RESULT = (token*7 + pos) & 0xFFFF before its done pulse on the last
// kernel.  Request 2: die 1 SM 1 faults; request 3: die 1 posts a different
// RESULT.  ENABLE = 0 instances of the bridge and command processor must
// drive every output 0.  Prints PASS/FAIL per check, LAT lines, and
// TB_GPU_HOST_BRIDGE PASS|FAIL.  Icarus 11 (-g2012) or Verilator --timing.
// ---------------------------------------------------------------------------
module tb_gpu_host_bridge;
    localparam integer ND = 2, NSM = 2, CB = 8, IMW = 13, NIM = 100, NK = 3;
    localparam [63:0] SQB = 64'h0000, CQB = 64'h1000, PRB = 64'h10000, MSIA = 64'h0F000;

    // ------------------------------------------------------------------ clocks and reset
    reg clk_host = 0, clk_sm = 0, clk_mem = 0, clk_link = 0, por_n = 0;
    always #2000 clk_host = ~clk_host;                         // 4000 ps
    always begin #416 clk_sm = 1'b1; #417 clk_sm = 1'b0; end    // 833 ps
    always #500 clk_mem = ~clk_mem;                            // 1000 ps
    always #450 clk_link = ~clk_link;                          // 900 ps
    wire rst_mem_n, rst_link_n, rst_sm_n, rst_host_n;
    ot_gpu_reset_ctrl #(.ENABLE(1)) u_rst (.por_n(por_n), .clk_mem(clk_mem), .clk_link(clk_link), .clk_sm(clk_sm),
        .clk_host(clk_host), .rst_mem_n(rst_mem_n), .rst_link_n(rst_link_n), .rst_sm_n(rst_sm_n),
        .rst_host_n(rst_host_n));

    // ------------------------------------------------------------------ host interface (as in ot_gpu_hbm_system)
    reg         s_awvalid = 0, s_wvalid = 0, s_arvalid = 0;
    reg  [11:0] s_awaddr = 0, s_araddr = 0;
    reg  [31:0] s_wdata = 0;
    wire        s_awready, s_wready, s_bvalid, s_arready, s_rvalid;
    wire [31:0] s_rdata;
    wire [1:0]  s_bresp, s_rresp;
    wire        m_arvalid, m_awvalid, m_wvalid, m_rready, m_wlast, m_bready, irq;
    wire [63:0] m_araddr, m_awaddr, m_wdata;
    wire [7:0]  m_wstrb, m_arlen, m_awlen;
    wire [2:0]  m_arsize, m_awsize;
    reg         m_rvalid = 0, m_bvalid = 0;
    reg  [63:0] m_rdata = 0;
    wire        eng_start, eng_done, eng_fault, eng_clr_req, eng_clr_ack;
    wire [15:0] eng_token, eng_pos, eng_next_token;
    wire [3:0]  eng_slot;
    wire [23:0] kv_base;
    wire [31:0] eng_cycles;
    wire        pb_we, pb_re;
    wire [11:0] pb_waddr, pb_raddr;
    wire [15:0] pb_wdata;
    reg  [15:0] pb_q;
    reg  [15:0] pbuf [0:4095];
    always @(posedge clk_host) begin
        if (pb_we) pbuf[pb_waddr] <= pb_wdata;
        if (pb_re) pb_q <= pbuf[pb_raddr];
    end
    wire arr_rst_n; wire [7:0] cfg_users; wire [15:0] cfg_prompt_len, cfg_gen_len;
    ot_host_if #(.NSLOT(16), .MODE(0), .ENG_CTX(16), .NW(16), .PLB(8), .CTX_MAX(64), .AW(24), .KVW(1024)) u_host (
        .clk(clk_host), .rst_n(rst_host_n),
        .s_awvalid(s_awvalid), .s_awready(s_awready), .s_awaddr(s_awaddr), .s_wvalid(s_wvalid), .s_wready(s_wready),
        .s_wdata(s_wdata), .s_wstrb(4'hF), .s_bvalid(s_bvalid), .s_bready(1'b1), .s_bresp(s_bresp),
        .s_arvalid(s_arvalid), .s_arready(s_arready), .s_araddr(s_araddr), .s_rvalid(s_rvalid), .s_rready(1'b1),
        .s_rdata(s_rdata), .s_rresp(s_rresp),
        .m_arvalid(m_arvalid), .m_arready(1'b1), .m_araddr(m_araddr), .m_arlen(m_arlen), .m_arsize(m_arsize),
        .m_rvalid(m_rvalid), .m_rready(m_rready), .m_rdata(m_rdata), .m_rresp(2'b00), .m_rlast(1'b1),
        .m_awvalid(m_awvalid), .m_awready(1'b1), .m_awaddr(m_awaddr), .m_awlen(m_awlen), .m_awsize(m_awsize),
        .m_wvalid(m_wvalid), .m_wready(1'b1), .m_wdata(m_wdata), .m_wstrb(m_wstrb), .m_wlast(m_wlast),
        .m_bvalid(m_bvalid), .m_bready(m_bready), .m_bresp(2'b00), .irq(irq),
        .pb_we(pb_we), .pb_waddr(pb_waddr), .pb_wdata(pb_wdata), .pb_re(pb_re), .pb_raddr(pb_raddr), .pb_q(pb_q),
        .eng_start(eng_start), .eng_token(eng_token), .eng_pos(eng_pos), .eng_slot(eng_slot), .kv_base(kv_base),
        .eng_done(eng_done), .eng_next_token(eng_next_token), .eng_cycles(eng_cycles), .eng_fault(eng_fault),
        .eng_clr_req(eng_clr_req), .eng_clr_ack(eng_clr_ack),
        .arr_rst_n(arr_rst_n), .cfg_users(cfg_users), .cfg_prompt_len(cfg_prompt_len), .cfg_gen_len(cfg_gen_len),
        .pr_re(1'b0), .pr_user(8'd0), .pr_pos(16'd0), .tok_valid(1'b0), .tok_user(8'd0), .tok_pos(16'd0),
        .tok_id(16'd0), .users_done(8'd0), .arr_fault(1'b0));

    // ------------------------------------------------------------------ behavioural host memory (AXI4 single beats)
    reg [63:0] hmem [0:24575];                                 // 0x00000 .. 0x2FFFF
    integer rd_wait = -1, mi;
    reg [63:0] rd_a;
    integer f_axi = 0;
    always @(posedge clk_host) begin
        m_rvalid <= 1'b0; m_bvalid <= 1'b0;
        if (m_arvalid) begin rd_a <= m_araddr; rd_wait <= 2; end            // arready = 1
        else if (rd_wait > 0) rd_wait <= rd_wait - 1;
        else if (rd_wait == 0) begin m_rvalid <= 1'b1; m_rdata <= hmem[rd_a[17:3]]; rd_wait <= -1; end
        if (m_awvalid != m_wvalid) begin $display("FAIL axi aw/w not presented together"); f_axi = f_axi + 1; end
        if (m_awvalid && m_wvalid) begin
            for (mi = 0; mi < 8; mi = mi + 1)
                if (m_wstrb[mi]) hmem[m_awaddr[17:3]][mi*8 +: 8] <= m_wdata[mi*8 +: 8];
            m_bvalid <= 1'b1;
        end
    end

    // ------------------------------------------------------------------ bridge, command processors
    reg         ld_v = 0, ld_target = 0;
    reg  [3:0]  ld_die = 0, ld_sm = 0;
    reg  [23:0] ld_addr = 0;
    reg  [63:0] ld_data = 0;
    wire        ld_rdy;
    wire [ND-1:0]     db_v, db_rdy, cpl_v, cpl_rdy;
    wire [ND*32-1:0]  db_tokpos;
    wire [ND*52-1:0]  cpl_data;
    wire [ND-1:0]     cmd_we;
    wire [CB-1:0]     cmd_addr;
    wire [63:0]       cmd_wdata, im_data;
    wire [ND*NSM-1:0] im_we;
    wire [IMW-1:0]    im_addr;
    wire              cdc_fault;
    ot_gpu_host_bridge #(.ENABLE(1), .ND(ND), .NSM(NSM), .CB(CB), .IMW(IMW)) u_bridge (
        .clk_host(clk_host), .rst_host_n(rst_host_n), .clk_sm(clk_sm), .rst_sm_n(rst_sm_n),
        .eng_start(eng_start), .eng_token(eng_token), .eng_pos(eng_pos), .eng_done(eng_done),
        .eng_next_token(eng_next_token), .eng_cycles(eng_cycles), .eng_fault(eng_fault),
        .eng_clr_req(eng_clr_req), .eng_clr_ack(eng_clr_ack),
        .ld_v(ld_v), .ld_rdy(ld_rdy), .ld_target(ld_target), .ld_die(ld_die), .ld_sm(ld_sm), .ld_addr(ld_addr),
        .ld_data(ld_data), .db_v(db_v), .db_rdy(db_rdy), .db_tokpos(db_tokpos), .cpl_v(cpl_v), .cpl_rdy(cpl_rdy),
        .cpl_data(cpl_data), .cmd_we(cmd_we), .cmd_addr(cmd_addr), .cmd_wdata(cmd_wdata), .im_we(im_we),
        .im_addr(im_addr), .im_data(im_data), .cdc_fault(cdc_fault));

    wire [ND*NSM-1:0]    launch_v;
    reg  [ND*NSM-1:0]    sm_done = 0, sm_fault = 0, res_v = 0;
    reg  [ND*NSM*32-1:0] res_data = 0;
    wire [ND*32-1:0]     launch_pc;
    wire [ND*16-1:0]     launch_token, launch_pos;
    genvar gd;
    generate for (gd = 0; gd < ND; gd = gd + 1) begin : g_die
        wire [15:0] cpl_token; wire [3:0] cpl_status; wire [31:0] cpl_cycles, st_kernels, st_busy;
        ot_gpu_cmdproc #(.ENABLE(1), .NSM(NSM), .NCMD(1 << CB)) u_cp (
            .clk(clk_sm), .rst_n(rst_sm_n), .cmd_we(cmd_we[gd]), .cmd_addr(cmd_addr), .cmd_wdata(cmd_wdata),
            .db_v(db_v[gd]), .db_rdy(db_rdy[gd]), .db_token(db_tokpos[gd*32 +: 16]),
            .db_pos(db_tokpos[gd*32+16 +: 16]),
            .launch_v(launch_v[gd*NSM +: NSM]), .launch_pc(launch_pc[gd*32 +: 32]),
            .launch_token(launch_token[gd*16 +: 16]), .launch_pos(launch_pos[gd*16 +: 16]),
            .sm_done(sm_done[gd*NSM +: NSM]), .sm_fault(sm_fault[gd*NSM +: NSM]), .res_v(res_v[gd*NSM +: NSM]),
            .res_data(res_data[gd*NSM*32 +: NSM*32]),
            .cpl_v(cpl_v[gd]), .cpl_rdy(cpl_rdy[gd]), .cpl_token(cpl_token), .cpl_status(cpl_status),
            .cpl_cycles(cpl_cycles), .st_kernels(st_kernels), .st_busy(st_busy));
        assign cpl_data[gd*52 +: 52] = {cpl_cycles, cpl_status, cpl_token};
    end endgenerate

    // ------------------------------------------------------------------ ENABLE = 0 instances
    wire        z_done, z_fault, z_clr_ack, z_ld_rdy, z_cdc;
    wire [15:0] z_next; wire [31:0] z_cycles;
    wire [ND-1:0] z_db_v, z_cpl_rdy, z_cmd_we; wire [ND*32-1:0] z_db_tokpos;
    wire [CB-1:0] z_cmd_addr; wire [63:0] z_cmd_wdata, z_im_data; wire [ND*NSM-1:0] z_im_we; wire [IMW-1:0] z_im_addr;
    ot_gpu_host_bridge #(.ENABLE(0), .ND(ND), .NSM(NSM), .CB(CB), .IMW(IMW)) u_bridge0 (
        .clk_host(clk_host), .rst_host_n(rst_host_n), .clk_sm(clk_sm), .rst_sm_n(rst_sm_n),
        .eng_start(eng_start), .eng_token(eng_token), .eng_pos(eng_pos), .eng_done(z_done),
        .eng_next_token(z_next), .eng_cycles(z_cycles), .eng_fault(z_fault),
        .eng_clr_req(eng_clr_req), .eng_clr_ack(z_clr_ack),
        .ld_v(ld_v), .ld_rdy(z_ld_rdy), .ld_target(ld_target), .ld_die(ld_die), .ld_sm(ld_sm), .ld_addr(ld_addr),
        .ld_data(ld_data), .db_v(z_db_v), .db_rdy(db_rdy), .db_tokpos(z_db_tokpos), .cpl_v(cpl_v),
        .cpl_rdy(z_cpl_rdy), .cpl_data(cpl_data), .cmd_we(z_cmd_we), .cmd_addr(z_cmd_addr), .cmd_wdata(z_cmd_wdata),
        .im_we(z_im_we), .im_addr(z_im_addr), .im_data(z_im_data), .cdc_fault(z_cdc));
    wire z_db_rdy, z_cpl_v; wire [NSM-1:0] z_lv; wire [31:0] z_pc, z_cc, z_k, z_b; wire [15:0] z_lt, z_lp, z_ct;
    wire [3:0] z_cs;
    ot_gpu_cmdproc #(.ENABLE(0), .NSM(NSM), .NCMD(1 << CB)) u_cp0 (
        .clk(clk_sm), .rst_n(rst_sm_n), .cmd_we(cmd_we[0]), .cmd_addr(cmd_addr), .cmd_wdata(cmd_wdata),
        .db_v(db_v[0]), .db_rdy(z_db_rdy), .db_token(db_tokpos[15:0]), .db_pos(db_tokpos[31:16]),
        .launch_v(z_lv), .launch_pc(z_pc), .launch_token(z_lt), .launch_pos(z_lp),
        .sm_done(sm_done[NSM-1:0]), .sm_fault(sm_fault[NSM-1:0]), .res_v(res_v[NSM-1:0]),
        .res_data(res_data[NSM*32-1:0]), .cpl_v(z_cpl_v), .cpl_rdy(1'b1), .cpl_token(z_ct), .cpl_status(z_cs),
        .cpl_cycles(z_cc), .st_kernels(z_k), .st_busy(z_b));
    integer f_en0 = 0, en0_samples = 0;
    reg en0_armed = 0;
    always @(negedge clk_sm) if (en0_armed) begin
        en0_samples = en0_samples + 1;
        if ({z_done, z_fault, z_clr_ack, z_ld_rdy, z_cdc, z_next, z_cycles, z_db_v, z_cpl_rdy, z_cmd_we, z_db_tokpos,
             z_cmd_addr, z_cmd_wdata, z_im_data, z_im_we, z_im_addr} !== 0 ||
            {z_db_rdy, z_cpl_v, z_lv, z_pc, z_cc, z_k, z_b, z_lt, z_lp, z_ct, z_cs} !== 0) begin
            if (f_en0 < 5) $display("FAIL enable0: an ENABLE=0 output is not 0 at %0t", $time);
            f_en0 = f_en0 + 1;
        end
    end

    // ------------------------------------------------------------------ expected graph and images
    function automatic [NSM-1:0] k_mask(input integer k);
        k_mask = (k == 0) ? 2'b01 : (k == 1) ? 2'b10 : 2'b11;
    endfunction
    function automatic [31:0] k_pc(input integer d, input integer k);
        k_pc = 32'h100 * (k + 1) + 32'h10 * d + 32'h4;
    endfunction
    function automatic [63:0] cmd_word(input integer d, input integer k);
        cmd_word = (k < NK) ? ((64'd1 << 60) | ({62'd0, k_mask(k)} << 44) | {32'd0, k_pc(d, k)}) : (64'd2 << 60);
    endfunction
    function automatic [IMW-1:0] im_a(input integer s, input integer a);
        im_a = (s == 0) ? (13'h0080 + a[12:0]) : (13'h1000 + a[12:0]);
    endfunction
    function automatic [63:0] im_word(input integer d, input integer s, input integer a);
        reg [31:0] h;
        begin
            h = a * 32'h9E3779B1 + d * 32'h85EBCA6B + s * 32'hC2B2AE35;
            im_word = {8'hD0, d[3:0], s[3:0], 16'(a), h};
        end
    endfunction
    function automatic [15:0] f_tok(input [15:0] tok, input [15:0] pos);
        f_tok = 16'((32'(tok) * 7 + 32'(pos)) & 32'hFFFF);
    endfunction

    // ------------------------------------------------------------------ loader delivery monitor (clk_sm)
    integer cmd_cnt [0:ND-1][0:3];
    integer im_cnt [0:ND-1][0:NSM-1][0:NIM-1];
    integer f_load = 0, n_ldw = 0, ld_d, ld_s, ld_k;
    always @(posedge clk_sm) if (rst_sm_n) begin
        if (cmd_we != 0 || im_we != 0) n_ldw = n_ldw + 1;
        if ((cmd_we != 0) && (im_we != 0)) begin $display("FAIL loader: cmd and im write in one cycle"); f_load = f_load + 1; end
        if (cmd_we != 0) begin
            if (cmd_we != 2'b01 && cmd_we != 2'b10) begin $display("FAIL loader: cmd_we %b not one-hot", cmd_we); f_load = f_load + 1; end
            ld_d = cmd_we[1] ? 1 : 0;
            if (cmd_addr >= 4 || cmd_wdata !== cmd_word(ld_d, cmd_addr)) begin
                $display("FAIL loader: die %0d cmd[%0d] = %h", ld_d, cmd_addr, cmd_wdata); f_load = f_load + 1;
            end else cmd_cnt[ld_d][cmd_addr] = cmd_cnt[ld_d][cmd_addr] + 1;
        end
        if (im_we != 0) begin
            ld_k = 0;
            for (ld_d = 0; ld_d < ND*NSM; ld_d = ld_d + 1) if (im_we[ld_d]) ld_k = ld_k + 1;
            if (ld_k != 1) begin $display("FAIL loader: im_we %b not one-hot", im_we); f_load = f_load + 1; end
            for (ld_d = 0; ld_d < ND; ld_d = ld_d + 1)
                for (ld_s = 0; ld_s < NSM; ld_s = ld_s + 1)
                    if (im_we[ld_d*NSM + ld_s]) begin
                        ld_k = int'(im_addr) - int'(im_a(ld_s, 0));
                        if (ld_k < 0 || ld_k >= NIM || im_data !== im_word(ld_d, ld_s, ld_k)) begin
                            $display("FAIL loader: die %0d sm %0d im[%h] = %h", ld_d, ld_s, im_addr, im_data);
                            f_load = f_load + 1;
                        end else im_cnt[ld_d][ld_s][ld_k] = im_cnt[ld_d][ld_s][ld_k] + 1;
                    end
        end
    end

    // ------------------------------------------------------------------ steps: issue checks and latencies
    integer mode = 0;                       // 0 normal, 1 die 1 SM 1 faults on kernel 1, 2 die 1 RESULT differs
    reg [15:0] prompt [0:4];
    integer plen = 5, step_i = 0, f_db = 0, f_step = 0, n_steps = 0, n_done = 0;
    reg [15:0] exp_tok, exp_fb, cur_tok, cur_pos;
    reg        step_live = 0;
    real t_es, t_ld, lat_sl_min = 1e30, lat_sl_max = 0, lat_sl_sum = 0, lat_de_min = 1e30, lat_de_max = 0,
         lat_de_sum = 0, lat_tot_sum = 0, lat;
    integer n_sl = 0, n_de = 0, first_launch_pending = 0;
    always @(posedge clk_host) if (rst_host_n) begin
        if (eng_start) begin
            exp_tok = (step_i < plen) ? prompt[step_i] : exp_fb;
            if (eng_pos !== step_i[15:0] || eng_token !== exp_tok) begin
                $display("FAIL doorbell: step %0d issued token %0d pos %0d, expected %0d %0d", step_i, eng_token,
                         eng_pos, exp_tok, step_i);
                f_db = f_db + 1;
            end
            cur_tok = eng_token; cur_pos = eng_pos; step_live = 1; n_steps = n_steps + 1;
            t_es = $realtime; first_launch_pending = 1;
        end
        if (eng_done) begin
            lat = $realtime - t_ld;
            if (mode == 0) begin
                n_de = n_de + 1; lat_de_sum = lat_de_sum + lat; lat_tot_sum = lat_tot_sum + ($realtime - t_es);
                if (lat < lat_de_min) lat_de_min = lat;
                if (lat > lat_de_max) lat_de_max = lat;
            end
            n_done = n_done + 1;
            if (mode == 0 && (eng_fault || eng_next_token !== f_tok(cur_tok, cur_pos))) begin
                $display("FAIL step result: pos %0d token %0d fault %0d (expected %0d)", cur_pos, eng_next_token,
                         eng_fault, f_tok(cur_tok, cur_pos));
                f_step = f_step + 1;
            end
            if (mode != 0 && !eng_fault) begin
                $display("FAIL step result: mode %0d did not raise eng_fault", mode); f_step = f_step + 1;
            end
            exp_fb = f_tok(cur_tok, cur_pos);
            step_i = step_i + 1; step_live = 0;
        end
    end

    // ------------------------------------------------------------------ SM stubs and stream-order monitor (clk_sm)
    integer cyc_sm = 0, f_order = 0, n_launch = 0, sd, ss, idx;
    integer kidx [0:ND-1];
    integer due [0:ND*NSM-1];
    integer kof [0:ND*NSM-1];
    reg [ND*NSM-1:0] run = 0, res_done = 0;
    reg [15:0] dtok [0:ND-1];
    reg [15:0] dpos [0:ND-1];
    integer n_db [0:ND-1];
    reg [NSM-1:0] lv;
    reg [15:0] rv;
    reg clear_stubs = 0;
    always @(posedge clk_sm) begin
        cyc_sm = cyc_sm + 1;
        sm_done <= 0; res_v <= 0;
        if (sm_done != 0) t_ld = $realtime;                        // the command processor samples done here
        if (clear_stubs) begin run = 0; res_done = 0; sm_fault <= 0; end
        else if (rst_sm_n) begin
            for (sd = 0; sd < ND; sd = sd + 1) begin
                if (db_v[sd] && db_rdy[sd]) begin
                    n_db[sd] = n_db[sd] + 1;
                    if (db_tokpos[sd*32 +: 32] !== {cur_pos, cur_tok} || !step_live) begin
                        $display("FAIL doorbell: die %0d got {pos %0d, tok %0d}, step issued {%0d, %0d}", sd,
                                 db_tokpos[sd*32+16 +: 16], db_tokpos[sd*32 +: 16], cur_pos, cur_tok);
                        f_db = f_db + 1;
                    end
                    dtok[sd] = db_tokpos[sd*32 +: 16]; dpos[sd] = db_tokpos[sd*32+16 +: 16]; kidx[sd] = 0;
                end
                lv = launch_v[sd*NSM +: NSM];
                if (lv != 0) begin
                    n_launch = n_launch + 1;
                    if (first_launch_pending) begin
                        lat = $realtime - t_es; first_launch_pending = 0;
                        if (mode == 0) begin
                            n_sl = n_sl + 1; lat_sl_sum = lat_sl_sum + lat;
                            if (lat < lat_sl_min) lat_sl_min = lat;
                            if (lat > lat_sl_max) lat_sl_max = lat;
                        end
                    end
                    if (run[sd*NSM +: NSM] != 0) begin
                        $display("FAIL stream order: die %0d launch %b while %b still running", sd, lv,
                                 run[sd*NSM +: NSM]);
                        f_order = f_order + 1;
                    end
                    if (kidx[sd] >= NK || lv !== k_mask(kidx[sd]) || launch_pc[sd*32 +: 32] !== k_pc(sd, kidx[sd])) begin
                        $display("FAIL stream order: die %0d kernel %0d mask %b pc %h", sd, kidx[sd], lv,
                                 launch_pc[sd*32 +: 32]);
                        f_order = f_order + 1;
                    end
                    if (launch_token[sd*16 +: 16] !== dtok[sd] || launch_pos[sd*16 +: 16] !== dpos[sd]) begin
                        $display("FAIL doorbell: die %0d launch token %0d pos %0d vs doorbell %0d %0d", sd,
                                 launch_token[sd*16 +: 16], launch_pos[sd*16 +: 16], dtok[sd], dpos[sd]);
                        f_db = f_db + 1;
                    end
                    kidx[sd] = kidx[sd] + 1;
                end
                for (ss = 0; ss < NSM; ss = ss + 1) begin
                    idx = sd * NSM + ss;
                    if (lv[ss]) begin
                        run[idx] = 1; res_done[idx] = 0; kof[idx] = kidx[sd] - 1;
                        due[idx] = cyc_sm + 10 + ($urandom % 291);
                    end else if (run[idx] && cyc_sm >= due[idx]) begin
                        if (mode == 1 && sd == 1 && ss == 1 && kof[idx] == 1) begin
                            sm_fault[idx] <= 1'b1; run[idx] = 0;
                        end else if (ss == 0 && kof[idx] == NK - 1 && !res_done[idx]) begin
                            rv = f_tok(launch_token[sd*16 +: 16], launch_pos[sd*16 +: 16]);
                            if (mode == 2 && sd == 1) rv = rv ^ 16'h0001;
                            res_v[idx] <= 1'b1; res_data[idx*32 +: 32] <= {16'd0, rv}; res_done[idx] = 1;
                            due[idx] = cyc_sm + 1 + ($urandom % 4);
                        end else begin
                            sm_done[idx] <= 1'b1; run[idx] = 0;
                        end
                    end
                end
            end
        end
    end

    // ------------------------------------------------------------------ cdc fault monitor, reset order
    integer f_cdc = 0, f_rst = 0;
    always @(posedge clk_host) if (rst_host_n && cdc_fault) begin
        if (f_cdc == 0) $display("FAIL cdc_fault raised"); f_cdc = f_cdc + 1;
    end
    real t_rm = -1, t_rl = -1, t_rs = -1, t_rh = -1;
    always @(posedge rst_mem_n)  t_rm = $realtime;
    always @(posedge rst_link_n) t_rl = $realtime;
    always @(posedge rst_sm_n)   t_rs = $realtime;
    always @(posedge rst_host_n) t_rh = $realtime;

    // ------------------------------------------------------------------ host (driver.py protocol)
    task automatic wr32(input [11:0] a, input [31:0] d);
        @(negedge clk_host); s_awaddr = a; s_wdata = d; s_awvalid = 1; s_wvalid = 1;
        do begin @(posedge clk_host); #1; end while (!s_bvalid);
        s_awvalid = 0; s_wvalid = 0;
    endtask
    task automatic rd32(input [11:0] a, output [31:0] d);
        @(negedge clk_host); s_araddr = a; s_arvalid = 1;
        do begin @(posedge clk_host); #1; end while (!s_rvalid);
        d = s_rdata; s_arvalid = 0;
    endtask
    task automatic ld_word(input t, input integer d, input integer s, input [23:0] a, input [63:0] w);
        @(negedge clk_host);
        while (!ld_rdy) @(negedge clk_host);
        ld_v = 1; ld_target = t; ld_die = d[3:0]; ld_sm = s[3:0]; ld_addr = a; ld_data = w;
    endtask

    integer sq_tail = 0, cq_head = 0, phase = 1, f_cq1 = 0, f_flt = 0, f_mis = 0, i, d, s, k, n;
    reg [63:0] w0, w1;
    reg [31:0] r;
    reg [15:0] gen [0:2];
    reg [15:0] eos0, eos1;
    task automatic submit(input integer slot, input [15:0] tag, input [15:0] p0, input [15:0] p1, input [15:0] p2,
                          input [15:0] p3, input [15:0] p4, input [15:0] e0, input [15:0] e1);
        reg [63:0] pa;
        begin
            pa = PRB + slot * 64'h400;
            prompt[0] = p0; prompt[1] = p1; prompt[2] = p2; prompt[3] = p3; prompt[4] = p4;
            hmem[pa[17:3]] = {p3, p2, p1, p0};
            hmem[pa[17:3] + 1] = {48'd0, p4};
            hmem[(SQB + 32 * sq_tail) / 8 + 0] = {16'd3, 16'd5, tag, 8'd3, 8'd1};   // max 3, plen 5, greedy|EOS
            hmem[(SQB + 32 * sq_tail) / 8 + 1] = pa;
            hmem[(SQB + 32 * sq_tail) / 8 + 2] = slot;
            hmem[(SQB + 32 * sq_tail) / 8 + 3] = {32'd0, e1, e0};
            step_i = 0;
            sq_tail = (sq_tail + 1) % 64;
            wr32(12'h01C, sq_tail);
        end
    endtask
    // poll the CQ by phase bit (driver.py HostDriver.poll); returns the entry, waits up to `lim` host cycles
    task automatic poll1(output [63:0] e0, output [63:0] e1, input integer lim, output integer ok);
        integer t;
        begin
            ok = 0;
            for (t = 0; t < lim && !ok; t = t + 1) begin
                @(negedge clk_host);
                e0 = hmem[(CQB + 16 * cq_head) / 8];
                e1 = hmem[(CQB + 16 * cq_head) / 8 + 1];
                if (e0[0] == phase[0]) ok = 1;
            end
            if (ok) begin
                cq_head = (cq_head + 1) % 256;
                if (cq_head == 0) phase = phase ^ 1;
            end
        end
    endtask
    task automatic ret_cq;
        begin wr32(12'h030, cq_head); wr32(12'h038, 1); end
    endtask
    task automatic chk_entry(input [63:0] e0, input [63:0] e1, input [1:0] kind, input [3:0] st, input [15:0] tag,
                             input [15:0] pos, input [15:0] tok, input [15:0] ngen, inout integer fcount,
                             input [8*16-1:0] nm);
        if (e0[2:1] !== kind || e0[7:4] !== st || e0[15:8] !== 8'(sq_tail - 1) || e0[31:16] !== tag ||
            e0[47:32] !== pos || e0[63:48] !== tok || e1[47:32] !== ngen) begin
            $display("FAIL %0s: CQ entry kind %0d status %0d slot %0d tag %h pos %0d token %0d gen %0d; expected kind %0d status %0d tag %h pos %0d token %0d gen %0d",
                     nm, e0[2:1], e0[7:4], e0[15:8], e0[31:16], e0[47:32], e0[63:48], e1[47:32], kind, st, tag, pos, tok, ngen);
            fcount = fcount + 1;
        end else
            $display("CQE %0s kind=%0d status=%0d slot=%0d tag=%h pos=%0d token=%0d cycles=%0d generated=%0d phase=%0d",
                     nm, e0[2:1], e0[7:4], e0[15:8], e0[31:16], e0[47:32], e0[63:48], e1[31:0], e1[47:32], e0[0]);
    endtask

    integer ok, seed;
    initial begin
        if (!$value$plusargs("SEED=%d", seed)) seed = 1;
        r = $urandom(seed);
        for (i = 0; i < 24576; i = i + 1) hmem[i] = 64'd0;
        for (d = 0; d < ND; d = d + 1) begin
            kidx[d] = 0; n_db[d] = 0; dtok[d] = 0; dpos[d] = 0;
            for (k = 0; k < 4; k = k + 1) cmd_cnt[d][k] = 0;
            for (s = 0; s < NSM; s = s + 1) for (k = 0; k < NIM; k = k + 1) im_cnt[d][s][k] = 0;
        end
        // ---- power-on reset
        #10000 por_n = 1;
        wait (rst_host_n === 1'b1);
        #1;
        if (!(t_rm > 0 && t_rl > 0 && t_rs > t_rm && t_rs > t_rl && t_rh > t_rs)) f_rst = f_rst + 1;
        $display("%s reset_order mem=%0.0f link=%0.0f sm=%0.0f host=%0.0f ps", f_rst ? "FAIL" : "PASS", t_rm, t_rl,
                 t_rs, t_rh);
        repeat (4) @(negedge clk_host);
        en0_armed = 1;

        // ---- driver load: graph and instruction images through the bridge loader
        for (d = 0; d < ND; d = d + 1)
            for (k = 0; k <= NK; k = k + 1) ld_word(1'b0, d, 0, k, cmd_word(d, k));
        for (d = 0; d < ND; d = d + 1)
            for (s = 0; s < NSM; s = s + 1)
                for (k = 0; k < NIM; k = k + 1) ld_word(1'b1, d, s, {11'd0, im_a(s, k)}, im_word(d, s, k));
        @(negedge clk_host); ld_v = 0;
        repeat (20) @(negedge clk_host);
        n = 0;
        for (d = 0; d < ND; d = d + 1) begin
            for (k = 0; k <= NK; k = k + 1) if (cmd_cnt[d][k] != 1) n = n + 1;
            for (s = 0; s < NSM; s = s + 1) for (k = 0; k < NIM; k = k + 1) if (im_cnt[d][s][k] != 1) n = n + 1;
        end
        if (n != 0 || n_ldw != ND * (NK + 1 + NSM * NIM)) begin
            $display("FAIL loader: %0d words not delivered exactly once, %0d writes seen", n, n_ldw);
            f_load = f_load + 1;
        end
        $display("%s loader_delivery writes=%0d (cmd %0d/die, im %0d/SM) errors=%0d", f_load ? "FAIL" : "PASS",
                 n_ldw, NK + 1, NIM, f_load);

        // ---- driver init (HostDriver.__init__)
        rd32(12'h000, r);
        if (r !== 32'h4F54_4849) begin $display("FAIL host: ID %h", r); f_cq1 = f_cq1 + 1; end
        rd32(12'h004, r);
        $display("INFO CAPS %h (slots %0d mode %0d eng_ctx %0d)", r, r[7:0], r[15:8], r[23:16]);
        wr32(12'h010, SQB[31:0]); wr32(12'h014, 0); wr32(12'h018, 6);
        wr32(12'h024, CQB[31:0]); wr32(12'h028, 0); wr32(12'h02C, 8);
        wr32(12'h040, MSIA[31:0]); wr32(12'h044, 0); wr32(12'h048, 32'h4F54); wr32(12'h04C, 1);
        wr32(12'h03C, 3); wr32(12'h008, 1);

        // ---- request 1: prompt of 5, max_new 3, EOS chosen not to trigger
        mode = 0;
        gen[0] = f_tok(16'd5555, 16'd4); gen[1] = f_tok(gen[0], 16'd5); gen[2] = f_tok(gen[1], 16'd6);
        eos0 = 16'hFFFE; eos1 = 16'hFFFD;
        for (i = 0; i < 3; i = i + 1) if (gen[i] == eos0 || gen[i] == eos1) eos0 = eos0 - 16'd7;
        submit(0, 16'h1234, 16'd11, 16'd22, 16'd333, 16'd4444, 16'd5555, eos0, eos1);
        for (i = 0; i < 3; i = i + 1) begin
            poll1(w0, w1, 200000, ok);
            if (!ok) begin $display("FAIL cq_request1: entry %0d never posted", i); f_cq1 = f_cq1 + 1; end
            else chk_entry(w0, w1, (i == 2) ? 2'd2 : 2'd1, (i == 2) ? 4'd2 : 4'd0, 16'h1234, 16'd4 + i[15:0], gen[i],
                           16'd1 + i[15:0], f_cq1, "cq_request1");
            if (ok && w0[0] !== 1'b1) begin $display("FAIL cq_request1: phase bit %0d", w0[0]); f_cq1 = f_cq1 + 1; end
        end
        ret_cq;
        repeat (200) @(negedge clk_host);
        if (hmem[(CQB + 16 * cq_head) / 8][0] !== 1'b0 || n_steps != 7 || n_done != 7) begin
            $display("FAIL cq_request1: extra entry or step count %0d/%0d (expected 7)", n_steps, n_done);
            f_cq1 = f_cq1 + 1;
        end
        rd32(12'h020, r);
        if (r !== 32'd1) begin $display("FAIL cq_request1: SQ_HEAD %0d", r); f_cq1 = f_cq1 + 1; end
        $display("%s cq_request1 entries=3 steps=%0d", f_cq1 ? "FAIL" : "PASS", n_steps);

        // ---- request 2: die 1 SM 1 faults on kernel 1 of the first step
        mode = 1;
        submit(1, 16'h2345, 16'd101, 16'd202, 16'd303, 16'd404, 16'd505, eos0, eos1);
        poll1(w0, w1, 200000, ok);
        if (!ok) begin $display("FAIL sm_fault: no CQ entry"); f_flt = f_flt + 1; end
        else chk_entry(w0, w1, 2'd2, 4'd7, 16'h2345, 16'd0, f_tok(16'd101, 16'd0), 16'd0, f_flt, "sm_fault");
        ret_cq;
        @(negedge clk_sm); clear_stubs = 1; repeat (4) @(negedge clk_sm); clear_stubs = 0;
        repeat (100) @(negedge clk_host);
        if (hmem[(CQB + 16 * cq_head) / 8][0] !== 1'b0) begin $display("FAIL sm_fault: extra CQ entry"); f_flt = f_flt + 1; end
        rd32(12'h00C, r);
        if (r[1] !== 1'b1) begin $display("FAIL sm_fault: STATUS.engine_fault not set (%h)", r); f_flt = f_flt + 1; end
        $display("%s sm_fault (die 1 SM 1 sm_fault -> cmdproc status 1 -> eng_fault -> CQ status engine_fault)",
                 f_flt ? "FAIL" : "PASS");

        // ---- request 3: die 1 posts a different RESULT on the first step
        mode = 2;
        submit(2, 16'h3456, 16'd7, 16'd8, 16'd9, 16'd10, 16'd11, eos0, eos1);
        poll1(w0, w1, 200000, ok);
        if (!ok) begin $display("FAIL result_mismatch: no CQ entry"); f_mis = f_mis + 1; end
        else chk_entry(w0, w1, 2'd2, 4'd7, 16'h3456, 16'd0, f_tok(16'd7, 16'd0), 16'd0, f_mis, "result_mismatch");
        ret_cq;
        repeat (100) @(negedge clk_host);
        if (hmem[(CQB + 16 * cq_head) / 8][0] !== 1'b0) begin $display("FAIL result_mismatch: extra CQ entry"); f_mis = f_mis + 1; end
        $display("%s result_mismatch (die 1 RESULT differs -> eng_fault -> CQ status engine_fault)",
                 f_mis ? "FAIL" : "PASS");

        // ---- summaries
        if (n_db[0] != n_steps || n_db[1] != n_steps) begin
            $display("FAIL doorbell: per-die doorbells %0d/%0d vs %0d steps", n_db[0], n_db[1], n_steps);
            f_db = f_db + 1;
        end
        $display("%s doorbell_tokpos steps=%0d (eng_start token/pos = teacher-forced prompt then fed-back token; each die's doorbell and launch carry it)",
                 f_db ? "FAIL" : "PASS", n_steps);
        $display("%s stream_order launches=%0d", f_order ? "FAIL" : "PASS", n_launch);
        $display("%s step_results", f_step ? "FAIL" : "PASS");
        $display("%s cdc_fault_zero", f_cdc ? "FAIL" : "PASS");
        $display("%s axi_dma", f_axi ? "FAIL" : "PASS");
        $display("%s enable0_outputs_zero samples=%0d", (f_en0 || en0_samples == 0) ? "FAIL" : "PASS", en0_samples);
        $display("LAT eng_start_to_first_launch_ps n=%0d min=%0.0f max=%0.0f mean=%0.1f", n_sl, lat_sl_min,
                 lat_sl_max, lat_sl_sum / n_sl);
        $display("LAT last_done_to_eng_done_ps n=%0d min=%0.0f max=%0.0f mean=%0.1f", n_de, lat_de_min, lat_de_max,
                 lat_de_sum / n_de);
        $display("LAT eng_start_to_eng_done_ps n=%0d mean=%0.1f", n_de, lat_tot_sum / n_de);
        n = f_rst + f_load + f_cq1 + f_flt + f_mis + f_db + f_order + f_step + f_cdc + f_axi + f_en0 +
            (en0_samples == 0);
        $display("TB_GPU_HOST_BRIDGE %s fails=%0d sim_time_ps=%0t", n ? "FAIL" : "PASS", n, $time);
        $finish;
    end
    initial begin
        #20000000000;
        $display("FAIL watchdog");
        $display("TB_GPU_HOST_BRIDGE FAIL fails=watchdog");
        $finish;
    end
endmodule
